(function(E){ const x = E["mkt-m1"] = E["mkt-m1"] || {units:{}}; x.units["mkt-2"] = {"grammar":{"id":"c-mkt-2-g","level":"B1","course":"marketing","unit":"mkt-2","title":"Parts of a group: most of, a third of, none of","titleTr":"Bir grubun parçaları: most of, a third of, none of","titleFa":"بخشی از یک گروه: most of، a third of، none of","formsTable":{"headers":{"en":["People in general","A known group (our data)"],"tr":["Genel olarak insanlar","Belirli bir grup (bizim verimiz)"],"fa":["مردم به‌طور کلی","یک گروه مشخص (داده‌های ما)"]},"rows":[["Most people like soft towels.","Most of our customers are 30 to 45."],["Some hotels buy in bulk.","Some of the hotels on our list buy every year."],["Few shoppers know the word.","None of them knew the word kilim."]]},"wrong":"Most of buyers are between 30 and 45.","right":"Most of the buyers are between 30 and 45.","blank":{"sentence":"About a third ___ them bought towels as a gift.","word":"of","distractors":["from","in"]},"wrong2":"Most of the people in our survey is under 45.","right2":"Most of the people in our survey are under 45.","blank2":{"sentence":"Most of the hotel buyers ___ about cost per wash.","word":"care","distractors":["cares","caring"]},"expParts":{"tryFrom":"blank","rule":[{"en":"Part of a known group: quantifier + of + the / our / them.","tr":"Belirli bir grubun parçası: miktar sözcüğü + of + the / our / them.","fa":"برای بخشی از یک گروه مشخص، کلمه‌ی مقدار را با of و بعد the، our یا them بیاور.","ex":"most of our customers, a third of them"},{"en":"People in general: no of, no the.","tr":"Genel olarak insanlar: of yok, the yok.","fa":"برای مردم به‌طور کلی، of و the نمی‌آید.","ex":"Most people like soft towels."},{"en":"The verb agrees with the noun after of.","tr":"Fiil, of'tan sonraki isimle uyumlu olur.","fa":"فعل با اسمِ بعد از of هماهنگ می‌شود.","ex":"Most of the buyers are... Most of the data is..."},{"en":"Fractions work the same way.","tr":"Kesirler de aynı şekilde kullanılır.","fa":"کسرها هم همین‌طورند.","ex":"a quarter of the buyers, half of them"}],"test":{"en":"Can you point to the group (our survey, these hotels)? Then use of + the / our / them.","tr":"Grubu gösterebiliyor musun (anketimiz, bu oteller)? O zaman of + the / our / them kullan.","fa":"می‌توانی به گروه اشاره کنی (نظرسنجی ما، این هتل‌ها)؟ پس of را با the، our یا them بیاور."},"contrast":{"en":"Turkish \"müşterilerin çoğu\" and Persian «بیشتر مشتری‌ها» have no word for the, so learners write \"most of customers\". English needs of + the / our / them.","tr":"Türkçede \"müşterilerin çoğu\" derken \"the\" karşılığı bir kelime yoktur; bu yüzden \"most of customers\" yazılır. İngilizcede belirli bir grup için of + the / our / them gerekir.","fa":"در فارسی «بیشتر مشتری‌ها» معادلی برای the ندارد؛ برای همین می‌نویسیم «most of customers». انگلیسی برای یک گروه مشخص of و بعد the، our یا them لازم دارد."}},"errorWatch":[{"find":["most of customers","most of buyers","most of people","most of hotels","some of customers","some of buyers","none of buyers","half of customers","a third of customers","a third of buyers"],"fix":{"en":"For a known group: of + the / our / them (\"most of our customers\"). For people in general: \"most people\".","tr":"Belirli bir grup için: of + the / our / them (\"most of our customers\"). Genel olarak insanlar için: \"most people\".","fa":"برای یک گروه مشخص: of با the، our یا them («most of our customers»). برای مردم به‌طور کلی: «most people»."}}]},"b2":{"id":"c-mkt-2-b2","level":"B2","track":"B2","course":"marketing","unit":"mkt-2","title":"One sentence, two facts: most of whom, some of which","titleTr":"Tek cümle, iki bilgi: most of whom, some of which","titleFa":"یک جمله، دو واقعیت: most of whom، some of which","formsTable":{"headers":{"en":["Form","For","Example"],"tr":["Yapı","Neyle","Örnek"],"fa":["ساختار","برای","مثال"]},"rows":[["most of whom","people","We spoke to twelve buyers, most of whom asked about washes."],["some of which","things","We tested five dyes, some of which faded."],["none of whom","people","We asked six designers, none of whom knew the word."]]},"wrong":"We asked 300 shoppers, most of them were between 30 and 45.","right":"We asked 300 shoppers, most of whom were between 30 and 45.","blank":{"sentence":"She called twelve hotel buyers, most of ___ asked about washes.","word":"whom","distractors":["who","them"]},"wrong2":"We tested five towels, two of whom faded.","right2":"We tested five towels, two of which faded.","blank2":{"sentence":"The factory tested five dyes, two of ___ faded after one wash.","word":"which","distractors":["whom","them"]},"expParts":{"tryFrom":"blank","rule":[{"en":"People: comma + quantifier + of whom.","tr":"İnsanlar: virgül + miktar sözcüğü + of whom.","fa":"برای آدم‌ها: ویرگول، کلمه‌ی مقدار و of whom.","ex":"twelve buyers, most of whom asked about washes"},{"en":"Things: comma + quantifier + of which.","tr":"Şeyler: virgül + miktar sözcüğü + of which.","fa":"برای چیزها: ویرگول، کلمه‌ی مقدار و of which.","ex":"five dyes, two of which faded"},{"en":"Not them, not who, after the comma.","tr":"Virgülden sonra them ya da who değil.","fa":"بعد از ویرگول نه them می‌آید، نه who.","ex":"300 shoppers, most of whom were under 45"}],"test":{"en":"Could you write \"Most of them...\" as a new sentence? Inside the same sentence, change them to whom or which.","tr":"\"Most of them...\" diye yeni bir cümle kurabilir misin? Aynı cümlenin içindeysen them yerine whom ya da which kullan.","fa":"می‌توانی «Most of them...» را جمله‌ی تازه‌ای بنویسی؟ اگر در همان جمله می‌مانی، them را به whom یا which تبدیل کن."},"contrast":{"en":"Persian says «که بیشترشان...» and Turkish adds \"ve çoğu...\" or a new sentence, so learners write \"most of them\" after a comma. English needs whom or which inside one sentence.","tr":"Türkçede bu bilgi \"ve çoğu...\" ile ya da yeni bir cümleyle eklenir; bu yüzden virgülden sonra \"most of them\" yazılır. İngilizcede tek cümle içinde whom ya da which gerekir.","fa":"در فارسی می‌گوییم «که بیشترشان...»؛ برای همین بعد از ویرگول most of them می‌نویسیم. انگلیسی در یک جمله whom یا which لازم دارد."}},"errorWatch":[{"find":["most of who","some of who","none of who","many of who","two of who","towels, two of whom","dyes, some of whom","dyes, two of whom"],"fix":{"en":"After of: whom for people, which for things (\"most of whom\", \"two of which\").","tr":"of'tan sonra: insanlar için whom, şeyler için which (\"most of whom\", \"two of which\").","fa":"بعد از of: برای آدم‌ها whom، برای چیزها which («most of whom»، «two of which»)."}}],"useIn":{"en":"B2: in your persona card, use one clause with most of whom, some of which or none of whom.","tr":"B2: persona kartında most of whom, some of which ya da none of whom içeren bir yan cümle kullan.","fa":"B2: در کارت مخاطب یک جمله با most of whom یا some of which یا none of whom بیاور."},"exitItem":{"from":"mkt-2","kind":"blank","prompt":"We asked 300 shoppers, a third of ___ had bought towels as gifts.","options":["them","who","whom"],"correct":2,"why":{"en":"whom: after 'of', a relative pronoun for people is whom. 'Them' starts a new sentence, and 'who' can't follow a preposition.","tr":"whom: 'of'tan sonra insanlar için ilgi zamiri whom'dur. 'Them' yeni bir cümle başlatır; 'who' edattan sonra gelmez.","fa":"whom درست است، چون بعد از of برای آدم‌ها whom می‌آید. them جمله‌ی تازه شروع می‌کند و who بعد از حرف اضافه نمی‌آید."}}},"vocab":{"id":"c-mkt-2-v","level":"B1","category":"vocab","course":"marketing","unit":"mkt-2","goals":["career"],"title":{"en":"Audience Research","tr":"Hedef Kitle Araştırması","fa":"تحقیق درباره‌ی مخاطب"},"cards":[{"word":"target audience","sentence":"Our target audience in the UK is online shoppers aged 30 to 45.","meaning":{"en":"The group of people a product or message is made for.","tr":"hedef kitle","fa":"مخاطب هدف"}},{"word":"respondent","sentence":"Two in five respondents had used the product on holiday.","gap":"respondents","accept":["respondents","respondent"],"meaning":{"en":"A person who answers a survey.","tr":"katılımcı (ankete cevap veren kişi)","fa":"پاسخ‌دهنده"}},{"word":"insight","sentence":"The best insight was simple: they already love the product.","meaning":{"en":"A new, useful understanding of what customers think or do.","tr":"içgörü","fa":"بینش؛ نکته‌ی کلیدی"}},{"word":"segment","sentence":"Hotel buyers are a separate segment with different needs.","meaning":{"en":"One group of customers with similar needs.","tr":"segment, pazar dilimi","fa":"بخش بازار (سگمنت)"}},{"word":"pain point","sentence":"Towels that go hard after a few washes are a real pain point for hotels.","meaning":{"en":"A problem that really bothers customers.","tr":"müşterinin en çok sıkıntı çektiği nokta (pain point)","fa":"دغدغه‌ی اصلی مشتری (پین‌پوینت)"}},{"word":"decision-maker","sentence":"In most hotels, the decision-maker is the procurement director.","meaning":{"en":"The person who decides what to buy.","tr":"karar verici","fa":"تصمیم‌گیرنده"}},{"word":"stereotype","sentence":"\"Germans love efficiency\" is a stereotype, not data.","meaning":{"en":"A fixed, simple idea about a group of people, often wrong.","tr":"kalıp yargı, klişe","fa":"کلیشه؛ قالب ذهنی"}},{"word":"purchase","sentence":"A third of them made the purchase as a gift.","meaning":{"en":"Something you buy, or the act of buying it.","tr":"satın alma","fa":"خرید"}},{"word":"sample","sentence":"Our sample was small: 300 people in one country.","meaning":{"en":"The group of people chosen for a survey.","tr":"örneklem","fa":"نمونه‌ی آماری"}},{"word":"behaviour","sentence":"Look at what customers do, not only what they say: behaviour is the best data.","meaning":{"en":"What people actually do.","tr":"davranış","fa":"رفتار"}}]},"judge":{"id":"c-mkt-2-j","course":"marketing","unit":"mkt-2","type":"judge","title":{"en":"Data or guesswork?","tr":"Veri mi, tahmin mi?","fa":"داده یا حدس؟"},"prompt":"Four lines from reader cards for a saffron brand that sells online. A survey of 200 buyers is available.","parts":["Based on data","Useful for the copy","Free of stereotypes"],"instruction":{"en":"Tap what each line does well. A line for the card needs all three.","tr":"Her satırın iyi yaptığı şeylere dokun. Karta girecek satırda üçü de olmalı.","fa":"روی کارهایی که هر خط درست انجام داده بزن. خطی که در کارت می‌آید باید هر سه را داشته باشد."},"items":[{"by":"AI tool","answer":"Emma, 28, lives in London and loves avocado toast.","present":[],"fix":{"en":"A cliché with no data behind it, and it tells the writer nothing about saffron. Use the survey.","tr":"Arkasında veri olmayan bir klişe ve yazara safran hakkında hiçbir şey söylemiyor. Anketi kullan.","fa":"کلیشه‌ای بدون داده که چیزی درباره‌ی زعفران به نویسنده نمی‌گوید. از نظرسنجی استفاده کن."}},{"by":"AI tool","answer":"As a typical Brit, she is polite but cold.","present":[],"fix":{"en":"A national stereotype, and no survey showed it. Delete it.","tr":"Ulusal bir kalıp yargı ve hiçbir anket bunu göstermedi. Sil.","fa":"کلیشه‌ی ملیتی است و هیچ نظرسنجی‌ای نشانش نداده. حذفش کن."}},{"by":"Good model","answer":"About a third of our buyers buy saffron as a gift, so the page must show the gift box.","present":["Based on data","Useful for the copy","Free of stereotypes"],"fix":null},{"by":"AI tool","answer":"Two in five respondents have never cooked with saffron.","present":["Based on data","Free of stereotypes"],"fix":{"en":"Correct and from the survey. Now make it useful: \"...so the copy must explain how to use it.\"","tr":"Doğru ve ankete dayanıyor. Şimdi işe yarar hâle getir: \"...so the copy must explain how to use it.\"","fa":"درست است و از نظرسنجی آمده. حالا آن را به کار متن بیاور: «...so the copy must explain how to use it.»"}}]},"writing":{"id":"c-mkt-2-w","title":{"en":"A reader card","tr":"Bir okur kartı","fa":"یک کارت مخاطب"},"course":"marketing","unit":"mkt-2","type":"writing","difficulty":"medium","modelBy":"FEschool","portfolio":null,"prompt":{"en":"Write a reader card (60-80 words) for your own product, or from these notes on a saffron brand: 200 buyers surveyed; most are 30-50; about a third buy it as a gift; two in five have never cooked with it; worry: \"Is it real saffron?\"; words from a review: \"a tiny box that changes the whole kitchen\". Say who the readers are, what bothers them and what the copy must do.","tr":"Kendi ürünün için ya da bir safran markasının şu notlarından okur kartı yaz (60-80 kelime): 200 alıcıyla anket; çoğu 30-50 yaşında; yaklaşık üçte biri hediye olarak alıyor; beşte ikisi hiç safranla yemek yapmamış; endişe: \"Is it real saffron?\"; bir yorumdan: \"a tiny box that changes the whole kitchen\". Okurun kim olduğunu, onu neyin rahatsız ettiğini ve metnin ne yapması gerektiğini yaz.","fa":"برای محصول خودت یا از روی این یادداشت‌های یک برند زعفران، کارت مخاطب بنویس (۶۰ تا ۸۰ کلمه): نظرسنجی از ۲۰۰ خریدار؛ بیشترشان ۳۰ تا ۵۰ ساله؛ حدود یک‌سوم برای هدیه می‌خرند؛ دو نفر از هر پنج نفر تا حالا با آن آشپزی نکرده‌اند؛ نگرانی: «Is it real saffron?»؛ از نظر یکی از خریداران: «a tiny box that changes the whole kitchen». بگو مخاطب کیست، چه چیزی آزارش می‌دهد و متن باید چه کند."},"model":"Most of our buyers are between 30 and 50, and about a third of them buy saffron as a gift. Two in five have never cooked with it, so they need a simple first recipe. Their biggest worry is \"Is it real saffron?\", so the page must show the lab test. One review says \"a tiny box that changes the whole kitchen\". We can use those words, in a warm tone, in our headline. Gift buyers are a separate segment.","frame":"Most of our buyers are ___, and about a third of them ___. Two in five ___, so ___. Their biggest worry is ___, so ___. One review says ___. We can ___.","words":[{"word":"most of"},{"word":"a third of"},{"word":"so"}],"minWords":60,"minSentences":4,"rubric":["Task done: who she is, what she did, what worries her, what the copy must do","Organised: facts first, then what they mean for the copy","Language: most of, a third of, none of, with the right verb","Tone: numbers and real words; no stereotypes"],"rubricI18n":{"tr":["Görev: kim olduğu, ne yaptığı, onu neyin endişelendirdiği, metnin ne yapması gerektiği","Düzen: önce bilgiler, sonra bunların metin için anlamı","Dil: most of, a third of, none of ve doğru fiil","Üslup: rakamlar ve gerçek sözler; kalıp yargı yok"],"fa":["کامل بودن کار: کیست، چه کرده، نگران چیست، متن باید چه کند","نظم: اول واقعیت‌ها، بعد معنایشان برای متن","زبان: most of، a third of، none of با فعل درست","لحن: عدد و حرف‌های واقعی؛ بدون کلیشه"]}},"speaking":{"id":"mkt-2","course":"marketing","unit":"mkt-2","topic":{"en":"Describing your readers with numbers","tr":"Okurlarını rakamlarla anlatmak","fa":"توصیف مخاطب‌ها با عدد"},"warmup":{"en":"Read one review of a product you like. Which words would you steal?","tr":"Sevdiğin bir ürünün yorumunu oku. Hangi kelimeleri alırdın?","fa":"نظر خریداران محصولی را که دوست داری بخوان. کدام کلمه‌ها را برمی‌داری؟"},"questions":[{"en":"Describe the readers of a brand you know in three facts, with numbers if you have them.","tr":"Tanıdığın bir markanın okurlarını, varsa rakamlarla, üç bilgiyle anlat.","fa":"مخاطب‌های برندی را که می‌شناسی با سه واقعیت توصیف کن، اگر عدد داری با عدد."},{"en":"Say what worries them most, in their own words.","tr":"Onları en çok neyin endişelendirdiğini kendi sözleriyle söyle.","fa":"با کلمه‌های خودشان بگو بیشتر از همه نگران چه هستند."},{"en":"A colleague asks: \"Can't we just use AI personas?\" Answer.","tr":"Bir iş arkadaşın soruyor: \"Can't we just use AI personas?\" Cevap ver.","fa":"یک همکار می‌پرسد: «Can't we just use AI personas?» جواب بده."}],"followups":[{"en":"Now describe the readers of your own product with two real facts.","tr":"Şimdi kendi ürününün okurlarını iki gerçek bilgiyle anlat.","fa":"حالا مخاطب‌های محصول خودت را با دو واقعیت درست توصیف کن."}],"expressions":[{"phrase":"In our survey of...,","meaning":{"en":"Gives the source and its size.","tr":"Kaynağı ve büyüklüğünü söyler.","fa":"منبع و اندازه‌اش را می‌گوید."}},{"phrase":"One review says...","meaning":{"en":"Brings in the customer's own words.","tr":"Müşterinin kendi sözlerini getirir.","fa":"حرف خود مشتری را می‌آورد."}},{"phrase":"So our copy has to...","meaning":{"en":"Turns a fact into a writing decision.","tr":"Bir bilgiyi yazı kararına çevirir.","fa":"یک واقعیت را به تصمیم نوشتن تبدیل می‌کند."}}],"model":"Our sample was 200 buyers. Most of them were between 30 and 50, and about a third of them made the purchase as a gift. The key insight: two in five had never cooked with it. One review says, 'Is it real saffron?' So our launch copy has to show the lab test and give one easy recipe. An AI persona can't tell us that, and neither can a competitor's page.","selfCheck":[{"en":"I gave three facts.","tr":"Üç bilgi verdim.","fa":"سه واقعیت گفتم."},{"en":"I said where the facts came from.","tr":"Bilgilerin nereden geldiğini söyledim.","fa":"گفتم واقعیت‌ها از کجا آمده‌اند."},{"en":"I said what they mean for the copy.","tr":"Metin için ne anlama geldiklerini söyledim.","fa":"گفتم برای متن چه معنایی دارند."},{"en":"Round 3 fitted in the time.","tr":"3. tur süreye sığdı.","fa":"دور سوم را در زمان تعیین‌شده تمام کردم."}]},"exit":{"id":"c-mkt-2-x","course":"marketing","unit":"mkt-2","type":"exit","items":[{"from":"mkt-2","kind":"blank","prompt":"Most ___ people in our focus group prefer the smaller pack.","options":["of the","the","of"],"correct":0,"point":2,"why":{"en":"of the: 'most of' needs 'the' before a specific group (the people in our group). 'Most the' drops of, and 'most of people' drops the.","tr":"of the: 'most of' belirli bir gruptan önce 'the' ister (gruptaki insanlar). 'Most the' of'u düşürür; 'most of people' the'yi düşürür.","fa":"of the درست است، چون most of برای گروه مشخص the می‌خواهد. most the بدون of است و most of people بدون the."}},{"from":"mkt-2","kind":"mcq","prompt":"Which is the best place to find your reader's own words?","options":["Customer reviews","Your company's slogan","Your competitor's logo"],"correct":0,"point":1,"why":{"en":"Customer reviews: they hold your reader's own words. Your slogan is your words, and a competitor's logo says nothing about readers.","tr":"Müşteri yorumları: okurunun kendi kelimelerini içerir. Sloganın senin kelimelerindir; rakibin logosu okurlarla ilgili bir şey söylemez.","fa":"نظرهای مشتری‌ها، چون حرف‌های خود خواننده در آن‌هاست. شعار برند حرف خودت است و لوگوی رقیب چیزی درباره‌ی خواننده نمی‌گوید."}},{"from":"mkt-2","kind":"mcq","prompt":"Which reader-card line should you cut?","options":["A third of buyers ask about delivery.","She is a typical luxury lover.","Many reviews mention the smell."],"correct":1,"point":1,"why":{"en":"'She is a typical luxury lover' is a guess, not data. The other two lines come from what buyers asked and wrote.","tr":"'She is a typical luxury lover' veri değil, tahmindir. Diğer iki satır alıcıların sorduklarından ve yazdıklarından gelir.","fa":"«She is a typical luxury lover» حدس است، نه داده. دو خط دیگر از چیزهایی آمده‌اند که خریدارها پرسیده و نوشته‌اند."}},{"from":"mkt-1","kind":"blank","prompt":"Before the app, our readers ___ wait a week for the newsletter.","options":["used to","was used to","use to"],"correct":0,"point":2,"why":{"en":"used to: a past habit that stopped. 'Was used to' means 'was familiar with', and 'use to' needs did before it.","tr":"used to: artık olmayan geçmiş bir alışkanlık. 'Was used to' 'alışkındı' demektir; 'use to' öncesinde did ister.","fa":"used to درست است، چون عادتی در گذشته بود که تمام شده. was used to یعنی «عادت داشت» و use to قبلش did لازم دارد."}},{"from":"mkt-1","kind":"mcq","prompt":"Voice stays the same. What can change with the moment?","options":["Tone","Who you are","The truth"],"correct":0,"point":1,"why":{"en":"Tone changes with the moment. Who you are is your voice, and the truth never changes.","tr":"Ton ana göre değişir. Kim olduğun senin sesindir; doğru ise asla değişmez.","fa":"لحن با موقعیت عوض می‌شود. اینکه کی هستی صدای برند است و حقیقت هم هیچ‌وقت عوض نمی‌شود."}},{"from":"mkt-1","kind":"blank","prompt":"Ten years ago, ___ you use to sell online?","options":["did","do","were"],"correct":0,"point":2,"why":{"en":"did: questions about a past habit use did + use to. 'Do' is the present, and 'were' doesn't go with use to.","tr":"did: geçmiş alışkanlık soruları did + use to kullanır. 'Do' şimdiki zamandır; 'were' use to ile gelmez.","fa":"did درست است، چون سؤال درباره‌ی عادت گذشته با did و use to می‌آید. do زمان حال است و were با use to نمی‌آید."}}]},"explain":{"id":"c-mkt-2-e","course":"marketing","unit":"mkt-2","type":"explain","level":"B1","title":{"en":"Know your reader","tr":"Okurunu tanı","fa":"مخاطبت را بشناس"},"objective":{"en":"After this lesson, you can describe your reader with real data and customers' own words, not stereotypes.","tr":"Bu dersin sonunda okurunu kalıp yargılarla değil, gerçek verilerle ve müşterilerin kendi sözleriyle anlatabileceksin.","fa":"بعد از این درس می‌توانی مخاطبت را با داده‌های واقعی و حرف‌های خود مشتری‌ها توصیف کنی، نه با کلیشه."},"hook":{"en":"Good copy uses the reader's own words and answers the reader's real worries. You find both by listening to customers first, not by guessing who they are.","tr":"İyi metin okurun kendi sözlerini kullanır ve gerçek endişelerine cevap verir. İkisini de kim olduklarını tahmin ederek değil, önce müşterileri dinleyerek bulursun.","fa":"متن خوب از کلمه‌های خود مخاطب استفاده می‌کند و به نگرانی‌های واقعی‌اش جواب می‌دهد. هر دو را با گوش دادن به مشتری‌ها پیدا می‌کنی، نه با حدس زدن درباره‌ی اینکه چه کسانی هستند."},"stats":[{"label":{"en":"Key points","tr":"Ana nokta","fa":"نکته‌ی اصلی"},"value":"3"},{"label":{"en":"Key phrases","tr":"Anahtar ifade","fa":"عبارت کلیدی"},"value":"4"},{"label":{"en":"Practice tasks","tr":"Alıştırma","fa":"تمرین"},"value":"3"}],"points":[{"eyebrow":{"en":"The craft","tr":"Beceri","fa":"مهارت"},"head":{"en":"Build a reader card","tr":"Okur kartı hazırla","fa":"کارت مخاطب بساز"},"steps":[{"en":"Listen first, because surveys, reviews and support questions show what people really think.","tr":"Önce dinle, çünkü anketler, yorumlar ve destek ekibine gelen sorular insanların gerçekte ne düşündüğünü gösterir.","fa":"اول گوش بده، چون نظرسنجی‌ها، نظر خریداران و سؤال‌هایی که از پشتیبانی می‌پرسند نشان می‌دهند آدم‌ها واقعاً چه فکر می‌کنند.","ex":"Review of a mug: My coffee stays hot through a whole meeting."},{"en":"Note what readers did, want, dislike and worry about. An unanswered worry can stop a sale.","tr":"Okurların ne yaptığını, ne istediğini, neyi sevmediğini ve neden endişelendiğini not al. Cevapsız kalan bir endişe satışı durdurabilir.","fa":"یادداشت کن مخاطب‌ها چه کرده‌اند، چه می‌خواهند، از چه بدشان می‌آید و نگران چه هستند. نگرانیِ بی‌جواب ممکن است جلوی خرید را بگیرد.","ex":"Worry: Will a real ceramic mug survive the post?"},{"en":"Copy their exact words. Readers trust language that sounds like their own.","tr":"Kullandıkları kelimeleri aynen al. Okurlar kendi diline benzeyen metne güvenir.","fa":"کلمه‌های خودشان را عیناً بردار. مخاطب به متنی که شبیه حرف خودش است بیشتر اعتماد می‌کند.","ex":"Review: My towels go hard. Copy: A towel that never goes hard."},{"en":"Cut anything with no source. A stereotype can insult readers and doesn't tell you what to write.","tr":"Kaynağı olmayan her şeyi çıkar. Kalıp yargı okuru kırabilir ve ne yazacağını da söylemez.","fa":"هر چیزی را که منبع ندارد حذف کن. کلیشه ممکن است مخاطب را برنجاند و به تو هم نمی‌گوید چه بنویسی.","ex":"Cut: Typical Londoner, loves luxury. Keep: a third buy it as a gift."}]},{"eyebrow":{"en":"The language it needs","tr":"Bunun için gereken dil","fa":"زبانی که لازم دارد"},"head":{"en":"Parts of a group: most of, a third of, none of","tr":"Bir grubun parçaları: most of, a third of, none of","fa":"بخشی از یک گروه: most of، a third of، none of"},"steps":[{"en":"Part of a known group: quantifier + of + the / our / them.","tr":"Belirli bir grubun parçası: miktar sözcüğü + of + the / our / them.","fa":"برای بخشی از یک گروه مشخص، کلمه‌ی مقدار را با of و بعد the، our یا them بیاور.","ex":"most of our customers, a third of them"},{"en":"People in general: no of, no the.","tr":"Genel olarak insanlar: of yok, the yok.","fa":"برای مردم به‌طور کلی، of و the نمی‌آید.","ex":"Most people like soft towels."},{"en":"The verb agrees with the noun after of.","tr":"Fiil, of'tan sonraki isimle uyumlu olur.","fa":"فعل با اسمِ بعد از of هماهنگ می‌شود.","ex":"Most of the buyers are... Most of the data is..."},{"en":"Fractions work the same way.","tr":"Kesirler de aynı şekilde kullanılır.","fa":"کسرها هم همین‌طورند.","ex":"a quarter of the buyers, half of them"}],"table":{"headers":{"en":["People in general","A known group (our data)"],"tr":["Genel olarak insanlar","Belirli bir grup (bizim verimiz)"],"fa":["مردم به‌طور کلی","یک گروه مشخص (داده‌های ما)"]},"rows":[["Most people like soft towels.","Most of our customers are 30 to 45."],["Some hotels buy in bulk.","Some of the hotels on our list buy every year."],["Few shoppers know the word.","None of them knew the word kilim."]]},"tip":{"en":"Turkish \"müşterilerin çoğu\" and Persian «بیشتر مشتری‌ها» have no word for the, so learners write \"most of customers\". English needs of + the / our / them.","tr":"Türkçede \"müşterilerin çoğu\" derken \"the\" karşılığı bir kelime yoktur; bu yüzden \"most of customers\" yazılır. İngilizcede belirli bir grup için of + the / our / them gerekir.","fa":"در فارسی «بیشتر مشتری‌ها» معادلی برای the ندارد؛ برای همین می‌نویسیم «most of customers». انگلیسی برای یک گروه مشخص of و بعد the، our یا them لازم دارد."},"wrong":"The most of our buyers are women.","right":"Most of our buyers are women."},{"eyebrow":{"en":"At work","tr":"İş yerinde","fa":"در محیط کار"},"head":{"en":"Saying where a number comes from","tr":"Bir rakamın nereden geldiğini söylemek","fa":"بگو هر عدد از کجا آمده"},"body":{"en":"A number with its source (\"in our survey of 300\") usually convinces more than an adjective. A small survey is fine if you say that it is small. No customers yet? Read reviews of similar products.","tr":"Kaynağıyla verilen bir rakam (\"300 kişilik anketimizde\") genellikle bir sıfattan daha ikna edicidir. Küçük bir anket, küçük olduğunu söylediğin sürece sorun değildir. Henüz müşterin yok mu? Benzer ürünlerin yorumlarını oku.","fa":"عددی که منبعش گفته شود («در نظرسنجی ۳۰۰ نفره‌مان») معمولاً از یک صفت قانع‌کننده‌تر است. نظرسنجی کوچک ایرادی ندارد، به شرطی که بگویی کوچک است. هنوز مشتری نداری؟ نظرهای مشتری‌ها درباره‌ی محصولات مشابه را بخوان."},"phrases":[{"phrase":"In our survey of...,","meaning":{"en":"Gives the source and its size.","tr":"Kaynağı ve büyüklüğünü söyler.","fa":"منبع و اندازه‌اش را می‌گوید."}},{"phrase":"One review says...","meaning":{"en":"Brings in the customer's own words.","tr":"Müşterinin kendi sözlerini getirir.","fa":"حرف خود مشتری را می‌آورد."}},{"phrase":"So our copy has to...","meaning":{"en":"Turns a fact into a writing decision.","tr":"Bir bilgiyi yazı kararına çevirir.","fa":"یک واقعیت را به تصمیم نوشتن تبدیل می‌کند."}},{"phrase":"pain point","meaning":{"en":"A problem that really bothers customers.","tr":"müşterinin en çok sıkıntı çektiği nokta (pain point)","fa":"دغدغه‌ی اصلی مشتری (پین‌پوینت)"}}]}],"example":{"eyebrow":{"en":"Worked example","tr":"Çözümlü örnek","fa":"مثال حل‌شده"},"head":{"en":"Turn a guess into a reader","tr":"Bir tahmini gerçek okura çevir","fa":"یک حدس را به مخاطب واقعی تبدیل کن"},"item":"Our customer is a typical young professional who loves luxury. Survey of 200 buyers: most are 30 to 45; a third buy our saffron as a gift; many ask how to use it.","answer":"Most of our buyers are 30 to 45. A third of them buy our saffron as a gift, and many ask how to use it. So our copy mentions gifts and explains how to use it.","walk":[{"en":"Ask of each word: where does this come from? \"Typical\" and \"loves luxury\" are guesses.","tr":"Her kelime için sor: Bu nereden geliyor? \"Typical\" ve \"loves luxury\" birer tahmin.","fa":"برای هر کلمه بپرس: این از کجا آمده؟ «typical» و «loves luxury» فقط حدس‌اند."},{"en":"Replace them with what the survey really shows.","tr":"Yerlerine anketin gerçekten gösterdiği şeyleri koy.","fa":"به‌جایشان چیزی را بگذار که نظرسنجی واقعاً نشان می‌دهد."},{"en":"Add what it means for the copy, because a reader card must change what you write.","tr":"Bunun metin için ne anlama geldiğini ekle, çünkü okur kartı yazdığın şeyi değiştirmelidir.","fa":"بعد بگو این نکته متن را چطور عوض می‌کند، چون کارت مخاطب باید چیزی را که می‌نویسی تغییر بدهد."}]},"quick":{"prompt":"The best source for a reader card is ___.","options":["what real customers say","what an AI tool imagines","what you would like"],"correct":0,"why":{"en":"what real customers say: their words and worries come from real experience, and you can use them in your copy.","tr":"what real customers say: sözleri ve endişeleri gerçek deneyimden gelir ve onları metninde kullanabilirsin.","fa":"جواب what real customers say است: حرف‌ها و نگرانی‌هایشان از تجربه‌ی واقعی می‌آید و می‌توانی در متنت از آن‌ها استفاده کنی."}},"remember":{"en":"Check each line: can you say where it comes from? If not, cut it. You can now build a reader card from real sources and turn it into writing decisions.","tr":"Her satırı kontrol et: Nereden geldiğini söyleyebiliyor musun? Söyleyemiyorsan çıkar. Artık gerçek kaynaklardan bir okur kartı hazırlayabilir ve onu yazı kararlarına çevirebilirsin.","fa":"هر خط را بررسی کن: می‌توانی بگویی از کجا آمده؟ اگر نه، حذفش کن. حالا می‌توانی از منبع‌های واقعی کارت مخاطب بسازی و از روی آن برای نوشتن تصمیم بگیری."},"b2Point":{"eyebrow":{"en":"B2 track","tr":"B2 yolu","fa":"مسیر B2"},"head":{"en":"One sentence, two facts: most of whom, some of which","tr":"Tek cümle, iki bilgi: most of whom, some of which","fa":"یک جمله، دو واقعیت: most of whom، some of which"},"steps":[{"en":"People: comma + quantifier + of whom.","tr":"İnsanlar: virgül + miktar sözcüğü + of whom.","fa":"برای آدم‌ها: ویرگول، کلمه‌ی مقدار و of whom.","ex":"twelve buyers, most of whom asked about washes"},{"en":"Things: comma + quantifier + of which.","tr":"Şeyler: virgül + miktar sözcüğü + of which.","fa":"برای چیزها: ویرگول، کلمه‌ی مقدار و of which.","ex":"five dyes, two of which faded"},{"en":"Not them, not who, after the comma.","tr":"Virgülden sonra them ya da who değil.","fa":"بعد از ویرگول نه them می‌آید، نه who.","ex":"300 shoppers, most of whom were under 45"}],"table":{"headers":{"en":["Form","For","Example"],"tr":["Yapı","Neyle","Örnek"],"fa":["ساختار","برای","مثال"]},"rows":[["most of whom","people","We spoke to twelve buyers, most of whom asked about washes."],["some of which","things","We tested five dyes, some of which faded."],["none of whom","people","We asked six designers, none of whom knew the word."]]},"body":{"en":"B2: in your persona card, use one clause with most of whom, some of which or none of whom.","tr":"B2: persona kartında most of whom, some of which ya da none of whom içeren bir yan cümle kullan.","fa":"B2: در کارت مخاطب یک جمله با most of whom یا some of which یا none of whom بیاور."}}}}; })(globalThis.COURSE_FILES = globalThis.COURSE_FILES || {});
